import { Input as InputControl } from "./input";
import { Numeric } from "./numeric";
import { Template } from "./templates";
import { Textarea } from "./textarea";

// Input is the bare control (function) + the Template namespace attached.
// Access: <Input />, <Input.Template.Simple label="..." />
const Input = Object.assign(InputControl, { Template });

export const AtomsFields = {
    Input,
    Textarea,
    Numeric,
};

export { Input, Numeric, Textarea };

import { Field as FieldPrimitive } from "@base-ui/react/field";
import { field } from "@/components/families/field";
import { cn } from "@/lib/cn";

// Bare control — text. No border, background, focus ring, invalid state or
// theme: all of that lives on the field.body that wraps this control. Uses
// FieldPrimitive.Control (Base UI) for the a11y wiring (id, aria-labelledby,
// aria-describedby, validation) when inside <Field.Root>; outside, it works
// as a plain input. The inputVariants.tone (5 values) is gone entirely —
// colour via the body's className.
export function Input({
    className,
    ...props
}: React.ComponentProps<typeof FieldPrimitive.Control>) {
    return (
        <FieldPrimitive.Control
            data-slot="input"
            className={cn(field.control(), className as string)}
            {...props}
        />
    );
}

import { Field as FieldPrimitive } from "@base-ui/react/field";
import { field } from "@/components/families/field";
import { cn } from "@/lib/cn";

// Bare control — multiline text. Same rule as Input: no box of its own.
// Variable height: the textarea uses rows; the field.body that wraps it uses
// min-h-control (not fixed), so it grows with content without a size variant.
// render={<textarea />} swaps the default element (input) for textarea while
// keeping Base UI Field's a11y wiring.
export function Textarea({
    className,
    rows,
    ...props
}: React.ComponentProps<typeof FieldPrimitive.Control> & {
    rows?: number;
}) {
    return (
        <FieldPrimitive.Control
            data-slot="textarea"
            render={<textarea rows={rows} />}
            className={cn(
                field.control(),
                "min-h-control",
                className as string,
            )}
            {...props}
        />
    );
}

import { Field as FieldPrimitive } from "@base-ui/react/field";
import { field } from "@/components/families/field";
import { cn } from "@/lib/cn";

// Bare control — numeric. This is the THESIS TEST: a new control, written
// from scratch, should be only its middle — without a single line of box
// styling (border, background, focus ring, invalid state, theme). All of
// that lives on the field.body that wraps this control.
//
// Behaviour: input type=number with step/min/max and keyboard increment
// (ArrowUp/ArrowDown respecting step). render={<input type="number" />}
// fixes the type while keeping Base UI Field's a11y wiring.
export type NumericProps = Omit<
    React.ComponentProps<typeof FieldPrimitive.Control>,
    "type"
> & {
    min?: number;
    max?: number;
    step?: number;
};

export function Numeric({
    className,
    min,
    max,
    step = 1,
    onKeyDown,
    ...props
}: NumericProps) {
    return (
        <FieldPrimitive.Control
            data-slot="numeric"
            render={<input type="number" min={min} max={max} step={step} />}
            className={cn(field.control(), className as string)}
            onKeyDown={(event) => {
                if (event.key === "ArrowUp" || event.key === "ArrowDown") {
                    const base = Number.parseFloat(event.currentTarget.value);
                    const current = Number.isFinite(base) ? base : 0;
                    const dir = event.key === "ArrowUp" ? 1 : -1;
                    const next = current + dir * (step ?? 1);
                    const clamped =
                        Number.isFinite(min) && next < (min as number)
                            ? (min as number)
                            : Number.isFinite(max) && next > (max as number)
                              ? (max as number)
                              : next;
                    event.currentTarget.value = String(clamped);
                }
                onKeyDown?.(event);
            }}
            {...props}
        />
    );
}

import { TemplateSimple } from "./simple";

// Template namespace — access via Input.Template.Simple.
// One template per component today; namespace prepared for more.
const Template = {
    Simple: TemplateSimple,
};

export { Template };

import type * as React from "react";
import { field } from "@/components/families/field";
import { Field } from "@/components/ui/field";
import { Input } from "../input";

// Input.Template.Simple — the tightest case. label, description, error,
// required, inset (inside, start/end), addon (outside, four sides) — all
// legitimate by rule 2 (content/behaviour). Survives with 7 props.
//
// The three rules:
// 1. No style of its own — no class, tv(), or hardcoded className beyond
//    field.inset() on the inset, which is a family piece (not template style).
// 2. No appearance props — no variant, size, color, contentClassName.
// 3. One className, going to the main piece (body) — the palette channel.
//
// Forbidden: contentProps / slotProps / any generic *Props bag. Props stay
// flat.
//
// Ceiling of 7 props: label, description, error, required, inset, addon,
// className. Input props (value, onChange, name, placeholder, type, etc.)
// are forwarded via ...props — they are behaviour, not template
// configuration. If an eighth is needed, stop and record it.
//
// inset: { start, end } — inside the body, before/after the control. Both
// sides can be filled at once (e.g. search icon + password toggle).
//
// addon: { inline: { start, end }, block: { start, end } } — outside the
// body, as siblings inside the row. Maps to the four data-side values of
// Field.Addon. Multiple sides can be filled at once; block addons use
// order-first/order-last so DOM order only matters for inline addons
// (inline-start before the body, inline-end after).

type SimpleProps = Omit<React.ComponentProps<typeof Input>, "className"> & {
    label?: React.ReactNode;
    description?: React.ReactNode;
    error?: React.ReactNode;
    required?: boolean;
    inset?: { start?: React.ReactNode; end?: React.ReactNode };
    addon?: {
        inline?: { start?: React.ReactNode; end?: React.ReactNode };
        block?: { start?: React.ReactNode; end?: React.ReactNode };
    };
    className?: string;
};

function Simple({
    label: labelContent,
    description,
    error,
    required,
    inset,
    addon,
    className,
    ...inputProps
}: SimpleProps) {
    return (
        <Field.Root>
            {labelContent ? (
                <Field.Label>
                    {labelContent}
                    {required ? <span aria-hidden="true">*</span> : null}
                </Field.Label>
            ) : null}
            <Field.Row>
                {addon?.block?.start ? (
                    <Field.Addon side="block-start">
                        {addon.block.start}
                    </Field.Addon>
                ) : null}
                {addon?.inline?.start ? (
                    <Field.Addon side="inline-start">
                        {addon.inline.start}
                    </Field.Addon>
                ) : null}

                <Field.Body className={className as string}>
                    {inset?.start ? (
                        <span className={field.inset()}>{inset.start}</span>
                    ) : null}
                    <Input {...inputProps} required={required} />
                    {inset?.end ? (
                        <span className={field.inset()}>{inset.end}</span>
                    ) : null}
                </Field.Body>

                {addon?.inline?.end ? (
                    <Field.Addon side="inline-end">
                        {addon.inline.end}
                    </Field.Addon>
                ) : null}
                {addon?.block?.end ? (
                    <Field.Addon side="block-end">
                        {addon.block.end}
                    </Field.Addon>
                ) : null}
            </Field.Row>
            {description ? (
                <Field.Description>{description}</Field.Description>
            ) : null}
            {error ? <Field.Error>{error}</Field.Error> : null}
        </Field.Root>
    );
}

export { Simple as TemplateSimple };
